const items = $input.all();

for (const item of items) {
  if (item.json.pn) {
    item.json.pn = item.json.pn.split('@')[0];
  }
}

return items;

const responseText = $input.first().json.data;

if (!responseText) {
    return [{ ditemukan: false }];
}

const jsonStart = responseText.indexOf('{');
const jsonEnd = responseText.lastIndexOf('}') + 1;
const jsonString = responseText.substring(jsonStart, jsonEnd);
const data = JSON.parse(jsonString);

if (!data.table.rows || data.table.rows.length === 0) {
    return [{
        ditemukan: false,
        pesan: "Nomor tidak terdaftar"
    }];
}

return data.table.rows.map(row => {
  return {
    nama: row.c[2]?.v || "Tidak Ada Nama",
    nomor_telepon: row.c[3]?.v || "",
    divisi: row.c[4]?.v || "",
    status: row.c[6]?.v || "",
    ditemukan: true
  };
});
